<script setup lang="ts">import { computed } from 'vue';import { CalendarDays,WalletCards,MapPinned,ArrowRight,AlertTriangle } from '@lucide/vue';import type { Itinerary } from '../types';const props=defineProps<{itinerary?:Itinerary|null;compact?:boolean}>();const activities=computed(()=>props.itinerary?.days?.flatMap(d=>d.activities)||[])</script>
<template><section class="itinerary-panel" :class="{compact}"><div class="section-heading"><div><span class="eyebrow">LIVE ITINERARY</span><h2>{{itinerary?.title||'当前行程'}}</h2></div><span v-if="itinerary" class="status-chip">规划中</span></div><template v-if="itinerary"><div class="trip-stats"><div><CalendarDays :size="17"/><span><strong>{{itinerary.travel_days||itinerary.days.length}} 天</strong><small>{{itinerary.destination||'目的地待定'}}</small></span></div><div><WalletCards :size="17"/><span><strong>¥{{itinerary.total_estimated_cost?.toLocaleString()||'—'}}</strong><small>预计总预算</small></span></div></div><div class="mini-timeline"><div v-for="day in itinerary.days.slice(0,compact?2:4)" :key="day.day" class="mini-day"><b>DAY {{String(day.day).padStart(2,'0')}}</b><div><span v-for="activity in day.activities.slice(0,3)" :key="activity.activity_id">{{activity.name}}</span></div></div></div><div v-if="itinerary.warnings?.length" class="warning-note"><AlertTriangle :size="16"/>{{itinerary.warnings[0]}}</div><RouterLink to="/trips" class="text-link"><MapPinned :size="16"/>查看完整地图与 {{activities.length}} 项安排<ArrowRight :size="15"/></RouterLink></template><div v-else class="itinerary-empty"><span>从一句话开始</span><p>告诉我目的地、日期和同行人，我会把对话整理成可执行行程。</p><RouterLink to="/chat" class="button primary">开始规划</RouterLink></div></section></template>
